<?php require_once __DIR__.'/config/database.php'; require_once __DIR__.'/config/auth.php'; require_once __DIR__.'/config/helpers.php'; require_login('teacher'); $page_title='QR sessions'; $st=db()->prepare("SELECT s.*,(SELECT COUNT(*) FROM attendance a WHERE a.session_id=s.id) present_count FROM attendance_sessions s WHERE s.teacher_id=? ORDER BY s.id DESC"); $st->execute([current_user()['id']]); $sessions=$st->fetchAll(); ?>
<?php include __DIR__.'/partials/header.php'; ?><div class="container reveal"><section class="panel"><div class="panel-head"><div><h3>All QR sessions</h3><span>Open a session to display its QR code.</span></div><a class="btn btn-primary" href="create_session.php">＋ New session</a></div><div class="table-wrap"><?php if($sessions): ?><table><thead><tr><th>Subject</th><th>Date</th><th>Expires</th><th>Present</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($sessions as $s): $active=strtotime($s['expires_at'])>time(); ?><tr><td><strong><?=e($s['subject'])?></strong></td><td><?=e(date('d M Y',strtotime($s['session_date'])))?></td><td><?=e(date('h:i A',strtotime($s['expires_at'])))?></td><td><?=intval($s['present_count'])?></td><td><span class="badge <?=$active?'badge-success':'badge-neutral'?>"><?=$active?'Active':'Expired'?></span></td><td><a class="btn btn-secondary" href="attendance_qr.php?id=<?=intval($s['id'])?>">Open QR</a></td></tr><?php endforeach; ?></tbody></table><?php else: ?><div class="empty"><div class="empty-icon">▦</div><strong>No sessions yet</strong><br>Create your first attendance session.</div><?php endif; ?></div></section></div><?php include __DIR__.'/partials/footer.php'; ?>